     1→import { ColumnSchema, DataScope, TableSchema } from '../types/analytics';
     2→import { applyDataScope } from './dataScope';
     3→
     4→/**
     5→ * 智能问数推荐问题生成：完全基于所选数据源的真实表结构（应用问数范围 scope 过滤后），
     6→ * 按指标/维度标注（缺失时按列类型回退推导）组合出多种分析意图的自然语言提示，
     7→ * 替代一切硬编码示例，保证提示内容与实际可查询的数据一致。
     8→ */
     9→
    10→/** 列的可读标签：优先中文描述，剥掉括号注释（如 "销售金额(元)" → "销售金额"），回退列名 */
    11→function colLabel(c: ColumnSchema): string {
    12→  const raw = (c.description || c.name).trim();
    13→  return raw.replace(/[(（][^)）]*[)）]/g, '').trim() || c.name;
    14→}
    15→
    16→/** 表的可读标签：优先显示名，回退表名 */
    17→function tableLabel(t: TableSchema): string {
    18→  return (t.displayName || t.name).trim();
    19→}
    20→
    21→function isMetricCol(c: ColumnSchema): boolean {
    22→  if (c.isMetric) return true;
    23→  if (c.isDimension || c.isPrimaryKey) return false;
    24→  // 回退推导：未标注时数值列视为指标
    25→  return c.type === 'number';
    26→}
    27→
    28→function isDimensionCol(c: ColumnSchema): boolean {
    29→  if (c.isDimension) return true;
    30→  if (c.isMetric || c.isPrimaryKey) return false;
    31→  // 回退推导：日期/类别/短文本列视为维度
    32→  return c.type === 'date' || c.type === 'category' || c.type === 'string';
    33→}
    34→
    35→/**
    36→ * 基于真实 Schema 生成推荐问题（已应用 scope 白名单过滤）。
    37→ * 跨表轮转取模板，保证多张表都有曝光；结果去重并以 max 为上限。
    38→ */
    39→export function generateSchemaSuggestions(
    40→  tables: TableSchema[],
    41→  scope?: DataScope | null,
    42→  max: number = 12
    43→): string[] {
    44→  const scoped = applyDataScope(Array.isArray(tables) ? tables : [], scope);
    45→  const out: string[] = [];
    46→  const seen = new Set<string>();
    47→  const push = (s: string) => {
    48→    if (s && !seen.has(s)) {
    49→      seen.add(s);
    50→      out.push(s);
    51→    }
    52→  };
    53→
    54→  // 第一轮：每表产出 1 条"趋势/分布"主推荐，保证表间覆盖
    55→  for (const t of scoped) {
    56→    const metrics = t.columns.filter(isMetricCol);
    57→    const dims = t.columns.filter(isDimensionCol);
    58→    const dateDim = dims.find((c) => c.type === 'date');
    59→    const tn = tableLabel(t);
    60→    if (metrics.length > 0 && dateDim) {
    61→      push(`分析 ${tn} 的 ${colLabel(metrics[0])} 按 ${colLabel(dateDim)} 的变化趋势`);
    62→    } else if (metrics.length > 0 && dims.length > 0) {
    63→      push(`分析 ${tn} 的 ${colLabel(metrics[0])} 按 ${colLabel(dims[0])} 分布`);
    64→    } else if (dims.length > 0) {
    65→      push(`统计 ${tn} 各 ${colLabel(dims[0])} 的记录数量`);
    66→    } else if (metrics.length > 0) {
    67→      push(`统计 ${tn} 的 ${colLabel(metrics[0])} 总和与平均值`);
    68→    }
    69→  }
    70→
    71→  // 第二轮：每表产出"对比/TopN/占比"等进阶推荐，扩充候选池
    72→  for (const t of scoped) {
    73→    const metrics = t.columns.filter(isMetricCol);
    74→    const dims = t.columns.filter(isDimensionCol);
    75→    const tn = tableLabel(t);
    76→    if (metrics.length > 0 && dims.length > 0) {
    77→      const m0 = colLabel(metrics[0]);
    78→      const d0 = colLabel(dims[0]);
    79→      push(`对比 ${tn} 不同 ${d0} 的 ${m0}`);
    80→      push(`查询 ${tn} 中 ${m0} 最高的前10个 ${d0}`);
    81→      push(`统计 ${tn} 各 ${d0} 的 ${m0} 占比`);
    82→      if (metrics.length > 1 && dims.length > 1) {
    83→        push(`分析 ${tn} 的 ${colLabel(metrics[1])} 按 ${colLabel(dims[1])} 分布`);
    84→      }
    85→    }
    86→  }
    87→
    88→  return out.slice(0, max);
    89→}
    90→
    91→/** 组装输入框占位提示：带一条真实推荐示例，超长截断 */
    92→export function buildQueryPlaceholder(suggestions: string[], fallback: string): string {
    93→  const first = suggestions[0];
    94→  if (!first) return fallback;
    95→  const clipped = first.length > 36 ? `${first.slice(0, 36)}...` : first;
    96→  return `用自然语言提问，如：${clipped}`;
    97→}
    98→

